import{_ as t,o as s,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const n="/assets/113_blobid0.CfwILWHc.png",r="/assets/105_blobid1.BB6PeaZd.png",a="/assets/99_blobid2.CTFdaESP.png",l="/assets/97_blobid3.ujk11wey.png",p="/assets/108_blobid4.uSYwuGae.png",u="/assets/104_blobid5.tGWpG4nt.png",c="/assets/106_blobid6.DCxdq7iU.png",m="/assets/115_blobid7.CNt5cWIO.png",h="/assets/120_blobid8.E3tE7v2T.png",d="/assets/98_blobid9.DSZPThc2.png",f="/assets/100_blobid10.YIScUMq7.png",g="/assets/114_blobid11.BwiBm9aM.png",x=JSON.parse('{"title":"Linux System RuiSu Installation Tutorial","description":"","frontmatter":{"title":"Linux System RuiSu Installation Tutorial"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/linux/linux-system-ruisu-installation-tutorial.md","filePath":"operations-knowledge-base/operating-system/linux/linux-system-ruisu-installation-tutorial.md","lastUpdated":1794311093000}'),_={name:"operations-knowledge-base/operating-system/linux/linux-system-ruisu-installation-tutorial.md"};function y(k,e,b,w,q,S){return s(),o("div",null,[...e[0]||(e[0]=[i('<p>Note: The prerequisite for installing RuiSu is to ensure that the network card is in the &quot;eth&quot; series.</p><p>Step 1: Install the recommended version of the kernel and reboot the machine after installation.</p><p>Step 2: After the reboot, verify that the kernel installation is correct. Then, download the 91YUN RuiSu installation script, which will be automatically executed.</p><ol><li>Modify the network interface name.</li></ol><p>1.Use the &quot;ip address&quot; command to check the network interface name.</p><p><img src="'+n+'" alt=""></p><ol start="2"><li>Go to the network interface configuration file directory and use the &quot;ls&quot; command to view the names of the network interface configuration files.</li></ol><ul><li>cd /etc/sysconfig/network-scripts/</li></ul><p><img src="'+r+'" alt=""></p><ol start="3"><li>Use the &quot;mv&quot; command to change the name of the network interface configuration file, and use the &quot;ls&quot; command to check if the modification was successful.</li></ol><ul><li>mv &quot;ifcfg-***&quot; (where &quot;*&quot; represents the original network interface name) to &quot;ifcfg-eth*&quot; (if you have multiple network interfaces, you can increment the number after &quot;eth&quot;).</li></ul><p><img src="'+a+'" alt=""></p><ol start="4"><li>To change the network interface name within the file, you simply need to edit the file and remove or modify the network interface name. Make sure to remove any quotation marks if present.</li></ol><ul><li>vi ifcfg-eth*</li></ul><p><img src="'+l+'" alt=""></p><p>Press the &quot;i&quot; key to enter text input mode and make changes to the network card name.</p><p>DEVICE=eth*</p><p>NAME=eth*</p><p><img src="'+p+'" alt=""><img src="'+u+'" alt=""></p><p>5.To exit the text input mode, press the ESC key. Then, to enter the command mode, press Shift+: (colon). In the command mode, type &quot;wq&quot; and press Enter to save the modifications and exit the file.</p><p>6.You can use the &quot;cat&quot; command to view the contents of the file and verify if the modifications were successful.</p><ul><li>cat ifcfg-eth0</li></ul><p><img src="'+c+'" alt=""></p><p>7.If you have a network configuration file in the &quot;Range&quot; format, you can use the following commands to modify it. Make sure the &quot;eth*&quot; name matches the name of the main network card.</p><ul><li>mv ifcfg-***-range0 ifcfg-eth*-range0</li></ul><ol start="8"><li><p>Restart the system #reboot</p></li><li><p>Verify if the network card name has been successfully modified.</p></li></ol><ul><li>ip address</li></ul><p><img src="'+m+'" alt=""></p><ol start="2"><li>Install the Speeder.</li></ol><p>1.Modify the specified optimized kernel：</p><p>Replace the CentOS 7.x kernel with： 3.10.0-229.1.2.el7.x86_64 ​​​​​​</p><ul><li>rpm -ivh <a href="http://soft.91yun.org/ISO/Linux/CentOS/kernel/kernel-3.10.0-229.1.2.el7.x86_64.rpm" target="_blank" rel="noreferrer">http://soft.91yun.org/ISO/Linux/CentOS/kernel/kernel-3.10.0-229.1.2.el7.x86_64.rpm</a> --force</li></ul><p>2.Check if the kernel is installed successfully.</p><ul><li>rpm -qa | grep kernel</li></ul><p><img src="'+h+'" alt=""></p><p>3.Restart the system #reboot</p><p>4.Check if the kernel replacement is successful</p><ul><li>uname -r</li></ul><p><img src="'+d+'" alt=""></p><p>5.Download the installation script and execute it automatically：</p><p>Method of installing Rui Su (LsRuisu):</p><ul><li>wget -N --no-check-certificate <a href="https://github.com/91yun/serverspeeder/raw/master/serverspeeder.sh" target="_blank" rel="noreferrer">https://github.com/91yun/serverspeeder/raw/master/serverspeeder.sh</a> &amp;&amp; yum install net-tools &amp;&amp; bash serverspeeder.sh</li></ul><p>Enter &quot;y&quot; and press Enter to continue.</p><p><img src="'+f+'" alt="">Enter <code>y</code> here and press Enter to continue</p><p>6.After the installation is completed, check the running status of Rui Su (LsRuisu) by using the following command:</p><ul><li>/serverspeeder/bin/serverSpeeder.sh status</li></ul><p><img src="'+g+'" alt=""></p><p>7.To enable Rui Su (LsRuisu) to start automatically on boot, follow these steps:</p><ul><li>echo &quot;service serverSpeeder start&quot; &gt;&gt; /etc/rc.d/rc.local &amp;&amp; chmod +x /etc/rc.d/rc.local</li></ul><p>Error Resolution:</p><p>serverspeeder.sh: line 141: ifconfig: command not found</p><p>The main reason for encountering this issue is that the system does not come with <code>ipconfig</code> installed in most cases.</p><p>Therefore, to resolve this, you simply need to install <code>ipconfig</code> using the following command:</p><p>yum install upgrade</p><p>yum install net-tools</p><p>Common Commands:</p><p>Restarting Speed:</p><p>/serverspeeder/bin/serverSpeeder.sh restart</p><p>Checking Speed status:</p><p>/serverspeeder/bin/serverSpeeder.sh status</p><p>Uninstalling Speed:</p><p>chattr -i /serverspeeder/etc/apx* &amp;&amp; /serverspeeder/bin/serverSpeeder.sh uninstall -f</p>',62)])])}const T=t(_,[["render",y]]);export{x as __pageData,T as default};
